    }
    <div class="relative px-8 py-24 text-center">
        <h1 class="text-4xl md:text-5xl font-bold text-white">@Model.Heading</h1>
        @if (!string.IsNullOrEmpty(Model.Subheading))
        {
            <p class="mt-4 text-lg text-slate-200 max-w-2xl mx-auto">@Model.Subheading</p>
        }
    </div>
</section>

