    <img src="@Model.ImageUrl" alt="@Model.Caption" class="w-full rounded-lg" />
    @if (!string.IsNullOrEmpty(Model.Caption))
    {
        <figcaption class="text-sm text-slate-500 mt-2 text-center">@Model.Caption</figcaption>
    }
</figure>

@model Umbraco.Bench.Umbraco.Models.Blocks.QuoteModel
<blockquote class="border-l-4 border-slate-900 pl-6 my-8 italic text-xl text-slate-800">
    <p>&ldquo;@Model.QuoteText&rdquo;</p>
    @if (!string.IsNullOrEmpty(Model.Author))
    {
        <footer class="mt-2 text-sm text-slate-500 not-italic">&mdash; @Model.Author</footer>
    }
</blockquote>

