@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<Umbraco.Bench.Umbraco.Models.BlogFrontPage>
@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@Model.Name</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-white text-slate-900">
    <main class="max-w-3xl mx-auto px-6 py-10">
        @await Html.GetBlockGridHtmlAsync(Model, "blocks")

        <section>
            <h2 class="text-2xl font-bold mb-6">Latest posts</h2>
            <ul class="space-y-10">
                @foreach (var post in Model.Children<Umbraco.Bench.Umbraco.Models.BlogPost>().OrderByDescending(p => p.PublishDate))
                {
                    <li>
                        <a href="@post.Url()" class="block group">
                            @{
                                var thumbnail = post.FeaturedImage;
                            }
                            @if (thumbnail != null)
                            {
                                <img src="@thumbnail.GetCropUrl(width: 1200, height: 630)" alt="@post.Name" class="w-full h-56 object-cover rounded-lg mb-4" />
                            }
                            <h3 class="text-xl font-semibold group-hover:underline">@post.Name</h3>
                            <p class="text-sm text-slate-500 mt-1">@post.PublishDate.ToString("MMMM d, yyyy")</p>
                            <p class="mt-2 text-slate-700">@post.Excerpt</p>
                        </a>
                    </li>
                }
            </ul>
        </section>
    </main>
</body>
</html>

