        }
        <header class="mt-4 mb-8">
            <h1 class="text-4xl font-bold">@Model.Name</h1>
            <p class="text-sm text-slate-500 mt-2">@Model.PublishDate.ToString("MMMM d, yyyy")</p>
            @{
                var featured = Model.FeaturedImage;
            }
            @if (featured != null)
            {
                <img src="@featured.GetCropUrl(width: 1600, height: 800)" alt="@Model.Name" class="w-full h-80 object-cover rounded-lg mt-6" />
            }
        </header>
        @await Html.GetBlockGridHtmlAsync(Model, "blocks")
    </article>
</body>
</html>
